```js
function shapeEl(type, cx, cy, r, parent, cls) {
  const c = TYPES[type].color;
  let n;
  switch (TYPES[type].shape) {
    case "square": n = el("rect", { x: cx - r, y: cy - r, width: 2 * r, height: 2 * r, rx: 2, fill: c }, parent); break;
    case "circle": n = el("circle", { cx, cy, r, fill: c }, parent); break;
    case "diamond": n = el("rect", { x: cx - r * .9, y: cy - r * .9, width: 1.8 * r, height: 1.8 * r, rx: 1.5, fill: c, transform: `rotate(45 ${cx} ${cy})` }, parent); break;
    case "triangle": n = el("path", { d: `M ${cx} ${cy - r * 1.15} L ${cx + r * 1.1} ${cy + r * .8} L ${cx - r * 1.1} ${cy + r * .8} Z`, fill: c }, parent); break;
    default: n = el("path", { d: hexPath(cx, cy, r * 1.08), fill: c }, parent);
  }
  n.classList.add("shape"); if (cls) n.classList.add(cls);
  return n;
}
function hexPath(cx, cy, r) { let d = ""; for (let i = 0; i < 6; i++) { const a = Math.PI / 3 * i - Math.PI / 6; d += (i ? "L" : "M") + (cx + r * Math.cos(a)).toFixed(1) + " " + (cy + r * Math.sin(a)).toFixed(1) + " "; } return d + "Z"; }
```

