  }

  /* ── 因果链 ───────────────────────────────────────── */
  function chainOf(id) {
    const anc = new Set(), desc = new Set();
    (function up(x) { CH[x].cause.forEach(p => { if (CH[p] && !anc.has(p)) { anc.add(p); up(p); } }); })(id);
